} function gc_premium_doc_save( $post_id ) { if ( ! isset( $_POST['gc_premium_doc_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['gc_premium_doc_nonce'] ) ), 'gc_premium_doc_save' ) ) { return; } if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) { return; } if ( isset( $_POST['gc_doc_file_id'] ) ) { update_post_meta( $post_id, 'gc_doc_file_id', absint( $_POST['gc_doc_file_id'] ) ); } if ( isset( $_POST['gc_doc_tier'] ) ) { $tier_val = absint(wp_unslash($_POST['gc_doc_tier'])); if(!isset(gc_tiers()[$tier_val])) $tier_val=(int)array_key_first(gc_tiers()); update_post_meta( $post_id, 'gc_doc_tier', $tier_val ); } } add_action( 'save_post_gc_premium_doc', 'gc_premium_doc_save' ); function gc_premium_doc_enqueue_media( $hook ) { global $post_type; if ( 'gc_premium_doc' === $post_type ) { wp_enqueue_media(); } } add_action( 'admin_enqueue_scripts', 'gc_premium_doc_enqueue_media' ); function gc_premium_doc_download_url( $post_id ) { return wp_nonce_url( add_query_arg( 'gc_download', $post_id, home_url( '/' ) ), 'gc_download_' . $post_id ); } function gc_handle_premium_download() { if ( empty( $_GET['gc_download'] ) ) { return; } $post_id = absint( $_GET['gc_download'] ); if ( ! isset( $_GET['_wpnonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_GET['_wpnonce'] ) ), 'gc_download_' . $post_id ) ) { wp_die( esc_html__( 'This download link has expired. Please go back to your dashboard and try again.', 'game-changers' ), 403 ); } if ( ! is_user_logged_in() || ! ( current_user_can( 'administrator' ) || in_array( 'premium_member', wp_get_current_user()->roles, true ) ) ) { wp_die( esc_html__( 'Please log in with your Premium Membership account to download this file.', 'game-changers' ), 403 ); } $doc_tier = (int) ( get_post_meta( $post_id, 'gc_doc_tier', true ) ?: 1 ); $user_tier = gc_get_user_premium_tier( get_current_user_id() ); if ( $doc_tier > $user_tier ) { wp_die( esc_html__( 'This document is part of Tier 2 (₦5,000) Premium access. Upgrade your membership to unlock it.', 'game-changers' ), 403 ); } $file_id = get_post_meta( $post_id, 'gc_doc_file_id', true ); $path = $file_id ? get_attached_file( $file_id ) : false; if ( ! $path || ! file_exists( $path ) ) { wp_die( esc_html__( 'File not found.', 'game-changers' ), 404 ); } nocache_headers(); header( 'Content-Description: File Transfer' ); header( 'Content-Type: ' . ( get_post_mime_type( $file_id ) ?: 'application/octet-stream' ) ); header( 'Content-Disposition: attachment; filename="' . basename( $path ) . '"' ); header( 'Content-Length: ' . filesize( $path ) ); readfile( $path ); exit; } add_action( 'template_redirect', 'gc_handle_premium_download' ); function gc_render_approve_button( $submission_id ) { $approved = get_post_meta( $submission_id, 'gc_premium_approved', true ); if ( $approved ) { $user_id = (int) $approved; $user = get_userdata( $user_id ); if ( $user ) { echo '<span style="color:#0a7a2f;font-weight:600;">✓ ' . esc_html__( 'Login active', 'game-changers' ) . '</span> '; echo '<a href="' . esc_url( get_edit_user_link( $user_id ) ) . '">' . esc_html__( '(view account)', 'game-changers' ) . '</a><br>'; gc_render_tier_control( $user_id ); return; } } ?>
