} function gc_handle_set_tier() { if ( empty( $_GET['gc_action'] ) || 'set_tier' !== $_GET['gc_action'] || empty( $_GET['user_id'] ) ) { return; } $user_id = absint( $_GET['user_id'] ); if ( ! current_user_can( 'edit_posts' ) || ! isset( $_GET['_wpnonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_GET['_wpnonce'] ) ), 'gc_set_tier_' . $user_id ) ) { wp_die( esc_html__( 'Security check failed.', 'game-changers' ) ); } $tier = absint($_GET['tier'] ?? 1); $tiers=gc_tiers(); if(!isset($tiers[$tier])) $tier=(int)array_key_first($tiers); update_user_meta( $user_id, 'gc_premium_tier', $tier ); wp_safe_redirect( remove_query_arg( array( 'gc_action', 'user_id', 'tier', '_wpnonce' ) ) ); exit; } add_action( 'admin_init', 'gc_handle_set_tier' ); function gc_get_premium_user_by_tag( $tag ) { if ( empty( $tag ) ) { return null; } $users = get_users( array( 'meta_key' => 'gc_premium_referral_tag', 'meta_value' => strtoupper( trim( $tag ) ), 'number' => 1, ) ); return ! empty( $users ) ? $users[0] : null; } function gc_count_premium_referrals( $user_id ) { $tag = get_user_meta( $user_id, 'gc_premium_referral_tag', true ); if ( ! $tag ) { return 0; } $members_q = new WP_Query( array( 'post_type' => 'gc_member', 'post_status' => 'publish', 'posts_per_page' => -1, 'fields' => 'ids', 'meta_query' => array( array( 'key' => 'gc_member_referrer_tag_raw', 'value' => $tag ) ), ) ); $submissions_q = new WP_Query( array( 'post_type' => 'gc_submission', 'post_status' => 'publish', 'posts_per_page' => -1, 'fields' => 'ids', 'meta_query' => array( array( 'key' => 'gc_referrer_tag_raw', 'value' => $tag ) ), ) ); return $members_q->found_posts + $submissions_q->found_posts; } function gc_signature_name_fallback() { return function_exists( 'gc_signature_name' ) ? gc_signature_name() : 'Game Changers Nigeria'; } function gc_handle_approve_premium() { if ( empty( $_GET['gc_action'] ) || 'approve_premium' !== $_GET['gc_action'] || empty( $_GET['submission_id'] ) ) { return; } $submission_id = absint( $_GET['submission_id'] ); if ( ! current_user_can( 'edit_posts' ) || ! isset( $_GET['_wpnonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_GET['_wpnonce'] ) ), 'gc_approve_premium_' . $submission_id ) ) { wp_die( esc_html__( 'Security check failed.', 'game-changers' ) ); } $email = get_post_meta( $submission_id, 'gc_email', true ); $name = get_the_title( $submission_id ); $tier = absint($_GET['tier'] ?? 1); $tiers=gc_tiers(); if(!isset($tiers[$tier])) $tier=(int)array_key_first($tiers); if ( ! is_email( $email ) ) { wp_die( esc_html__( 'This submission has no valid email on file.', 'game-changers' ) ); } $existing = get_user_by( 'email', $email ); if ( $existing ) { $existing->add_role( 'premium_member' ); $user_id = $existing->ID; $is_new = false; } else { $username = sanitize_user( current( explode( '@', $email ) ) . '-' . wp_generate_password( 4, false ), true ); $user_id = wp_insert_user( array( 'user_login' => $username, 'user_email' => $email, 'user_pass' => wp_generate_password( 20, true, true ), 'display_name' => $name, 'role' => 'premium_member', ) ); $is_new = true; } if ( is_wp_error( $user_id ) ) { wp_die( esc_html( $user_id->get_error_message() ) ); } update_post_meta( $submission_id, 'gc_premium_approved', $user_id ); update_user_meta( $user_id, 'gc_premium_tier', $tier ); if ( ! get_user_meta( $user_id, 'gc_premium_referral_tag', true ) && function_exists( 'gc_generate_membership_tag' ) ) { update_user_meta( $user_id, 'gc_premium_referral_tag', gc_generate_membership_tag() ); } if ( $is_new ) { if ( function_exists( 'gc_send_member_welcome_email' ) ) { gc_send_member_welcome_email( $email, $name ); } $user_obj = get_userdata( $user_id ); if ( $user_obj ) { retrieve_password( $user_obj->user_login ); } if ( function_exists( 'gc_dispatch_welcome_email' ) ) { $login_url = gc_page_url( 'premium-login' ); $subject = __( 'Set Your Password — Game Changers Premium', 'game-changers' ); $body = "Hello " . strtok( trim( $name ),