function gc_get_user_premium_tier( $user_id ) {
	$user_id = absint( $user_id );
	$tiers = function_exists( 'gc_tiers' ) ? gc_tiers() : array( 1 => array( 'name' => 'Tier 1' ) );
	if ( ! is_array( $tiers ) || empty( $tiers ) ) {
		$tiers = array( 1 => array( 'name' => 'Tier 1' ) );
